import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0007 — Stack di sviluppo locale: RustFS come S3, porte non standard","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0007-dev-stack.md","filePath":"adr/0007-dev-stack.md"}'),n={name:"adr/0007-dev-stack.md"};function s(r,e,c,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0007-—-stack-di-sviluppo-locale-rustfs-come-s3-porte-non-standard" tabindex="-1">ADR-0007 — Stack di sviluppo locale: RustFS come S3, porte non standard <a class="header-anchor" href="#adr-0007-—-stack-di-sviluppo-locale-rustfs-come-s3-porte-non-standard" aria-label="Permalink to &quot;ADR-0007 — Stack di sviluppo locale: RustFS come S3, porte non standard&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.6 (MinIO/AWS S3), §4.1 <code>deploy/docker</code></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, solo per lo sviluppo locale: lo spec cita MinIO come esempio di S3-compatibile; in produzione resta &quot;qualsiasi S3-compatibile&quot;</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Le immagini <code>minio/minio</code> e <code>quay.io/minio/minio</code> non sono più scaricabili senza autenticazione (ottobre 2026). Sulla macchina di sviluppo le porte 5432, 8081 e 8082 erano già occupate da altri servizi.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><strong>RustFS</strong> (<code>rustfs/rustfs</code>, Apache-2.0, API S3 compatibile con MinIO, console su 9001) come object store di sviluppo in <code>deploy/docker/compose.dev.yaml</code>; bucket creati da un init container <code>amazon/aws-cli</code>. Il servizio cloud parla S3 generico (<code>minio-go</code>/SDK), quindi nessun impatto sul codice.</li><li>Porte di sviluppo: PostgreSQL <strong>5433</strong> sull&#39;host, API cloud <strong>18081</strong>, gRPC <strong>18082</strong> (default in <code>config.go</code> e <code>cloud.dev.env</code>); Keycloak 8080.</li><li><code>make stack-reset</code> distrugge i volumi (necessario per re-importare <code>realm-memobrain.json</code>, che Keycloak importa solo su realm inesistente).</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>LocalStack</strong> — scartata: pesante, più lenta all&#39;avvio.</li><li><strong>Garage / SeaweedFS / versitygw</strong> — valide; RustFS scelta per compatibilità di configurazione con MinIO (variabili <code>*_ACCESS_KEY</code>, console) e documentazione.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>I test d&#39;integrazione con S3 (M2) useranno testcontainers con la stessa immagine; se RustFS cambiasse licenza o distribuzione, la sostituzione è confinata al compose.</p>',10)])])}const g=o(n,[["render",s]]);export{m as __pageData,g as default};
